    "misc.quest.step_sanitize_hood_title": "1. Sanitize the Hood",
    "misc.quest.step_sanitize_hood_desc": "Grab a 70% Alcohol Spray Bottle and spray inside the Laminar Flow Hood.",
    "misc.quest.step_hood_on_title": "2. Turn on the Laminar Flow",
    "misc.quest.step_hood_on_desc": "Click the Laminar Flow Hood switch to turn on the HEPA filter.",
    "misc.quest.step_cooker_heat_title": "3. Prepare the autoclave",
    "misc.quest.step_cooker_heat_desc": "Place a jar/bag in the Pressure Cooker or turn on the Industrial Burner.",
    "misc.quest.step_syringe_use_title": "4. Inoculate with Syringe",
    "misc.quest.step_syringe_use_desc": "Use the 10ml Syringe on a Liquid Culture jar or spawn.",
    "misc.quest.step_greenhouse_care_title": "5. Tend the Greenhouse",
    "misc.quest.step_greenhouse_care_desc": "Go to the Greenhouse and mist water or harvest a mature mushroom block.",
    "misc.quest.step_monotub_harvest_title": "6. Harvest from Monotub 24L",
    "misc.quest.step_monotub_harvest_desc": "Mix spawn with substrate, level it, and close the lid. Once colonized, move it to the LED rack and harvest with an empty hand.",
    "misc.quest.step_dry_pack_title": "7. Dehydrate mushrooms",
    "misc.quest.step_dry_pack_desc": "Place a fresh mushroom in the dehydrator and wait for the batch to finish. To sell, pack it in Mylar and seal it.",
    "misc.quest.step_sell_pack_title": "8. Sell at the Drive-Thru Emporium",
    "misc.quest.step_sell_pack_desc": "Bring sealed packs or the Delivery Crate to the South Road Emporium!",
