    "misc.quest.step_monotub_harvest_title": "6. Cosechar en el Monotub 24L",
    "misc.quest.step_monotub_harvest_desc": "Mezcla el spawn con el sustrato, nivela y cierra la tapa. Al colonizar, llévalo al estante LED y cosecha con la mano libre.",
    "misc.quest.step_dry_pack_title": "7. Deshidratar hongos",
